<form class="filter panel" method="get"><label>From date<input type="date" name="from" value="<?=e($_GET['from']??'')?>"></label><label>To date<input type="date" name="to" value="<?=e($_GET['to']??'')?>"></label><label>Status<select name="status"><option value="">All statuses</option><?php foreach(['pending','accepted','collected','cancelled','expired'] as $s):?><option value="<?=$s?>" <?=($_GET['status']??'')===$s?'selected':''?>><?=$s==='pending'?'Available':ucfirst($s)?></option><?php endforeach;?></select></label><button class="button">Filter</button><button class="button outline" name="export" value="csv">Export CSV</button><button class="plain" type="button" onclick="window.print()">Print</button></form><div class="table-wrap"><table><thead><tr><th>Donation</th><th>Donor</th><th>Orphanage</th><th>Servings</th><th>Status</th><th>Posted</th></tr></thead><tbody><?php foreach($rows as $d):?><tr><td><a class="text-link" href="<?=url('donation-details.php?id='.$d['id'])?>"><?=e($d['title'])?></a><small><?=e($d['city'])?></small></td><td><?=e($d['donor'])?></td><td><?=e($d['receiver']??'—')?></td><td><?=(int)$d['quantity']?></td><td><?=badge($d['status'])?></td><td><?=e($d['created_at'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty">No donations match these filters.</div><?php endif;?></div>